test('renderInvoiceText shows line-level discount for lines with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  // Should show line discount: (85000 * 10%) + (remaining * 2.5%) = 8500 + 2125 = 10625
  assert.match(text, /-€106\.25/);
});

test('renderInvoiceText does not show line-level discount when line has no discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const lineItemLine = lines.find((l) => l.includes('Design work'));
  assert.doesNotMatch(lineItemLine, /-€/);
});

test('renderInvoiceText shows voucher amount before total', () => {
  const { ok, value: invoice } = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(ok, true);
  const { ok: applyOk, value: withVoucher } = require('../src/invoices.js').applyVoucher(invoice, {
    code: 'SUMMER20',
    amount: 10000,
  });
