import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';

test('renderInvoiceText shows DRAFT for unsaved invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.match(text, /^DRAFT\n/);
});

test('renderInvoiceText shows invoice number for issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  assert.match(text, /^INV-2026-0001\n/);
});

test('renderInvoiceText includes customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.match(text, /Northwind Studio/);
});

test('renderInvoiceText formats line items with quantities and totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.match(text, /5 Design work \(hour\)/);
  assert.match(text, /€85\.00/);
  assert.match(text, /€425\.00/);
});

test('renderInvoiceText handles multiple line items', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.match(text, /3 Design work \(hour\)/);
  assert.match(text, /2 Icon set \(24 icons\)/);
  assert.match(text, /€255\.00/);
  assert.match(text, /€19\.60/);
});

test('renderInvoiceText shows total at the end', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.match(text, /Total: €514\.25$/);
});

test('renderInvoiceText sums multiple lines in total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'ICON-SET', qty: 10 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  // Line 2 (qty 10) gets bulk discount: 9800 * 2.5% = 245
  // New total: 52300 - 245 + (8925 + 2007) = €629.87
  assert.match(text, /Total: €629\.87$/);
});

test('renderInvoiceText formats prices with euro symbol and two decimals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.match(text, /€0\.50/);
  assert.match(text, /€50\.00/);
});

test('renderInvoiceText works with different customers', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const text1 = renderInvoiceText(invoice1);
  const text2 = renderInvoiceText(invoice2);
  assert.match(text1, /Northwind Studio/);
  assert.match(text2, /Kite & Co/);
});

test('renderInvoiceText returns multiline text', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 3 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  const lineCount = text.split('\n').length;
  assert.equal(lineCount, 7); // DRAFT, customer, line1, line2, subtotal, vat, total
});

test('renderInvoiceText includes all required elements in order', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'ICON-SET', qty: 1 },
    ],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.match(lines[2], /1 Design work/);
  assert.match(lines[3], /1 Icon set/);
  assert.match(lines[4], /Subtotal:/);
  assert.match(lines[5], /VAT:/);
  assert.match(lines[6], /Total:/);
});

test('renderInvoiceText shows VAT on its own line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  // qty 10 gets bulk discount: 85000 * 2.5% = 2125
  // VAT on (85000 - 2125): 82875 * 21% = €174.04
  assert.match(text, /VAT: €174\.04/);
});

test('renderInvoiceText shows discount line when discount is applied', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.match(text, /Discount: €/);
  assert.match(text, /VAT: €/);
});

test('renderInvoiceText does not show discount line when discount is zero', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 9 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.doesNotMatch(text, /^Discount:/m);
});

test('renderInvoiceText shows line-level discount for lines with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  }).value;
  const text = renderInvoiceText(invoice);
  // Should show line discount: (85000 * 10%) + (remaining * 2.5%) = 8500 + 2125 = 10625
  assert.match(text, /-€106\.25/);
});

test('renderInvoiceText does not show line-level discount when line has no discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const lineItemLine = lines.find((l) => l.includes('Design work'));
  assert.doesNotMatch(lineItemLine, /-€/);
});

test('renderInvoiceText shows voucher amount before total', () => {
  const { ok, value: invoice } = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(ok, true);
  const { ok: applyOk, value: withVoucher } = require('../src/invoices.js').applyVoucher(invoice, {
    code: 'SUMMER20',
    amount: 10000,
  });
  assert.equal(applyOk, true);
  const text = renderInvoiceText(withVoucher);
  assert.match(text, /Voucher: -€100\.00/);
  assert.match(text, /Voucher:.*Total:/s);
});

test('renderInvoiceText does not show voucher when not present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.doesNotMatch(text, /Voucher:/);
});

test('renderInvoiceText shows due date when invoice is issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;
  const text = renderInvoiceText(invoice);
  assert.match(text, /Due: 2026-11-06$/);
});

test('renderInvoiceText shows due date with different payment terms', () => {
  const invoiceNet14 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const textNet14 = renderInvoiceText(invoiceNet14);
  assert.match(textNet14, /Due: 2026-10-21$/);

  const invoiceEOM = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  }).value;
  const textEOM = renderInvoiceText(invoiceEOM);
  assert.match(textEOM, /Due: 2026-10-31$/);
});

test('renderInvoiceText shows paid amount when invoice has payments', () => {
  const { recordPayment } = require('../src/payments.js');
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const { ok, value: paid } = recordPayment(issued, { amount: 50000, date: '2026-10-07' });
  assert.equal(ok, true);

  const text = renderInvoiceText(paid);
  assert.match(text, /Paid: €500\.00$/);
});

test('renderInvoiceText shows total paid from multiple payments', () => {
  const { recordPayment } = require('../src/payments.js');
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 20 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const payment1 = recordPayment(issued, { amount: 50000, date: '2026-10-07' }).value;
  const payment2 = recordPayment(payment1, { amount: 30000, date: '2026-10-10' }).value;

  const text = renderInvoiceText(payment2);
  assert.match(text, /Paid: €800\.00$/);
});

test('renderInvoiceText does not show paid when no payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.doesNotMatch(text, /Paid:/);
});

test('renderInvoiceText shows all enhanced features together', () => {
  const { applyVoucher } = require('../src/invoices.js');
  const { recordPayment } = require('../src/payments.js');

  let invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 15, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 5 },
    ],
    terms: 'NET14',
  }).value;

  invoice = applyVoucher(invoice, { code: 'SUMMER', amount: 5000 }).value;
  invoice = issueInvoice(invoice, []).value;
  invoice = recordPayment(invoice, { amount: 100000, date: '2026-10-08' }).value;

  const text = renderInvoiceText(invoice);

  // Check for all enhanced features
  assert.match(text, /Design work.*-€/);
  assert.match(text, /Voucher: -€50\.00/);
  assert.match(text, /Due: 2026-10-21/);
  assert.match(text, /Paid: €1,000\.00/);
  assert.match(text, /Total:/);
});

