});

test('renderInvoiceText shows paid amount when invoice has payments', () => {
  const { recordPayment } = require('../src/payments.js');
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
