  const payment1 = recordPayment(issued, { amount: 50000, date: '2026-10-07' }).value;
  const payment2 = recordPayment(payment1, { amount: 30000, date: '2026-10-10' }).value;

  const text = renderInvoiceText(payment2);
  assert.match(text, /Paid: €800\.00$/);
});

test('renderInvoiceText does not show paid when no payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const text = renderInvoiceText(invoice);
  assert.doesNotMatch(text, /Paid:/);
});

test('renderInvoiceText shows all enhanced features together', () => {
  const { applyVoucher } = require('../src/invoices.js');
  const { recordPayment } = require('../src/payments.js');

  let invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 15, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 5 },
    ],
    terms: 'NET14',
  }).value;

  invoice = applyVoucher(invoice, { code: 'SUMMER', amount: 5000 }).value;
  invoice = issueInvoice(invoice, []).value;
  invoice = recordPayment(invoice, { amount: 100000, date: '2026-10-08' }).value;

  const text = renderInvoiceText(invoice);

  // Check for all enhanced features
  assert.match(text, /Design work.*-€/);
  assert.match(text, /Voucher: -€50\.00/);
  assert.match(text, /Due: 2026-10-21/);
  assert.match(text, /Paid: €1,000\.00/);
  assert.match(text, /Total:/);
});

